import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
from typing import Sequence, Dict, Any

def _define_hyperparameters():
    return {
        'learning_rate': 0.001, 'd_model': 256, 'num_blocks': 5,
        'dilations': [1, 2, 4, 8, 16], 'kernel_size': 7, 'dropout_rate': 0.1,
        'tau': 0.25, 'gru_hidden_dim': 256
    }

class DSConvDilatedBlock(nn.Module):
    d_model: int; kernel_size: int = 7; dilation: int = 1; dropout_rate: float = 0.1
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.LayerNorm()(x)
        h = nn.Conv(self.d_model, (self.kernel_size,), feature_group_count=self.d_model, padding='SAME', kernel_dilation=(self.dilation,))(h)
        h = nn.gelu(h)
        h = nn.Conv(self.d_model, (1,))(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        return x + h

class DSConvFeatureExtractor(nn.Module):
    d_model: int; num_blocks: int; dilations: Sequence[int]; kernel_size: int; dropout_rate: float
    @nn.compact
    def __call__(self, x, deterministic=True):
        h = nn.Dense(self.d_model)(x)
        h = nn.gelu(h)
        h = nn.Dropout(rate=self.dropout_rate)(h, deterministic=deterministic)
        for i in range(self.num_blocks):
            h = DSConvDilatedBlock(self.d_model, self.kernel_size, self.dilations[i], self.dropout_rate)(h, deterministic=deterministic)
        return h

def lse_pool(h: jnp.ndarray, tau: float) -> jnp.ndarray:
    x = h / tau
    m = jnp.max(x, axis=1, keepdims=True)
    return tau * (jnp.log(jnp.mean(jnp.exp(x - m), axis=1) + 1e-12) + jnp.squeeze(m, axis=1))

class AveragedMoE(nn.Module):
    d_output: int; task_type: str; d_model: int; num_blocks: int; dilations: Sequence[int]
    kernel_size: int; dropout_rate: float; tau: float; gru_hidden_dim: int
    @nn.compact
    def __call__(self, x, deterministic=True):
        features_seq = DSConvFeatureExtractor(self.d_model, self.num_blocks, self.dilations, self.kernel_size, self.dropout_rate)(x, deterministic=deterministic)

        # Expert 1: Pooling
        mean_vec = jnp.mean(features_seq, axis=1)
        lse_vec = lse_pool(features_seq, self.tau)
        pooled_vec = jnp.concatenate([mean_vec, lse_vec], axis=-1)

        # Expert 2: RNN
        rnn_vec = nn.RNN(nn.GRUCell(self.gru_hidden_dim))(features_seq)[:, -1, :]

        # Projection and Averaging
        d_expert = self.d_model * 2
        pooled_vec_proj = nn.Dense(d_expert)(pooled_vec)
        rnn_vec_proj = nn.Dense(d_expert)(rnn_vec)
        fused = 0.5 * pooled_vec_proj + 0.5 * rnn_vec_proj

        # Final Projection Head
        z = nn.LayerNorm()(fused)
        z = nn.Dense(self.d_model)(z)
        z = nn.gelu(z)
        z = nn.Dropout(rate=self.dropout_rate)(z, deterministic=deterministic)
        logits = nn.Dense(self.d_output)(z)

        if self.task_type == 'regression' and self.d_output == 1:
            return logits.squeeze(-1)
        return logits

class NetworkWrapper:
    def __init__(self, model_instance): self.network = model_instance
    def init(self, rng_key, dummy_input):
        params = self.network.init(rng_key, dummy_input, deterministic=True)
        return params['params']
    def apply(self, params, x, deterministic=True, rng_key=None):
        rngs = {'dropout': rng_key} if not deterministic else None
        return self.network.apply({'params': params}, x, deterministic=deterministic, rngs=rngs)

def create_network(hparams: Dict[str, Any]):
    model = AveragedMoE(
        d_output=hparams.get('d_output'), task_type=hparams.get('task_type'),
        d_model=hparams.get('d_model'), num_blocks=hparams.get('num_blocks'),
        dilations=tuple(hparams.get('dilations')), kernel_size=hparams.get('kernel_size'),
        dropout_rate=hparams.get('dropout_rate'), tau=hparams.get('tau'),
        gru_hidden_dim=hparams.get('gru_hidden_dim')
    )
    return NetworkWrapper(model)
